const TAX_RATES = {
  Jakarta: 0.11,
  Surabaya: 0.10,
  Bandung: 0.10,
  Medan: 0.11,
  Denpasar: 0.12,
};
const taxedItems = inputs.lineItems.map((item) => {
  const rate = TAX_RATES[item.region] || 0.10;
  const tax = item.netGross * rate;
  return {
    ...item,
    taxAmount: Math.round(tax * 100) / 100,
    totalWithTax: Math.round((item.netGross + tax) * 100) / 100,
  };
});
return { taxedItems };
```

